class Session {
  private cachedReportOwnerId?: string;

  setOwner(id: string) { this.cachedReportOwnerId = id; }

  generateReport() {
    if (!this.cachedReportOwnerId) return 'summary';
    return `detailed report for ${this.cachedReportOwnerId}`;
  }
}

class OrderProcessor {
  private promoCode?: string;

  loadPromo(code?: string) { this.promoCode = code; }

  calculateTotal(items: { price: number }[]) {
    let total = items.reduce((s, i) => s + i.price, 0);
    if (this.promoCode) total -= 10;
    return total;
  }
}

// Version A
class InvoiceCalculatorA {
  compute(lines: {amount: number}[]) {
    const adjustment = this.calculateAdjustment(lines);
    return this.total(lines) + adjustment;
  }
  private calculateAdjustment(lines: {amount: number}[]) { return 0; }
}

// Version B
class InvoiceCalculatorB {
  private adjustment?: number;
  compute(lines: {amount: number}[]) {
    this.adjustment = this.calculateAdjustment(lines);
    return this.total(lines) + (this.adjustment || 0);
  }
  private calculateAdjustment(lines: {amount: number}[]) { return 0; }
}
